def build(w, extra_x=True):
    c=np.cos(w*t); s=np.sin(w*t)
    cols=[np.ones_like(t),x,v,x**2,x**3,x*v,v**2,v*np.abs(v)]
    cols+= [c,s,c*x,s*x,c*v,s*v,c*x**2,s*x**2]
    return np.column_stack(cols)
def resid(p):
    X=build(p[0])
    b,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    return (X@b-y)
best=None
